inline void putid(Bytes&b,uint32_t x,unsigned t){if(x<t)b.push_back(x);else{x-=t;b.push_back(t+x/256);b.push_back(x%256);}}
inline Bytes lz(const Bytes&s){Bytes out;std::vector<int>tab(65536,-1),chain(s.size(),-1);size_t n=s.size(),i=0,lit=0;auto flush=[&](size_t e){while(lit<e){size_t k=std::min<size_t>(128,e-lit);out.push_back(k-1);out.insert(out.end(),s.begin()+lit,s.begin()+lit+k);lit+=k;}};while(i+4<=n){uint32_t v=r32(s.data()+i);unsigned hash=(v*2654435761u)>>16;int prev=tab[hash],bestprev=-1;chain[i]=prev;tab[hash]=i;size_t len=0;for(int steps=0;prev>=0&&i-size_t(prev)<=65535&&steps<128;steps++,prev=chain[prev]){if(r32(s.data()+prev)==v){size_t l=4;while(l<131&&i+l<n&&s[prev+l]==s[i+l])l++;if(l>len){len=l;bestprev=prev;if(l==131)break;}}}prev=bestprev;if(len>=4){flush(i);out.push_back(128+len-4);p16(out,i-prev);for(size_t j=1;j<len&&i+j+4<=n;j++){unsigned h=(r32(s.data()+i+j)*2654435761u)>>16;chain[i+j]=tab[h];tab[h]=i+j;}i+=len;lit=i;}else i++;}flush(n);return out;}
inline size_t quoted_end(const std::string&s,size_t p){if(p>=s.size()||s[p]!='"')throw std::runtime_error("complex string parse");p++;while(p<s.size()){char c=s[p++];if(c=='"')return p;if(c=='\\'){if(p==s.size())break;p++;}}throw std::runtime_error("complex unterminated string");}
inline std::vector<std::string> attrparts(const std::string&s){std::vector<std::string>out;if(s=="null"||s=="{}")return out;if(s.front()!='{'||s.back()!='}')throw std::runtime_error("complex attribute parse");size_t p=1;while(p+1<s.size()){size_t st=p;p=quoted_end(s,p);if(s[p++]!=':')throw std::runtime_error("complex attribute colon");if(s[p]=='"')p=quoted_end(s,p);else{while(p<s.size()&&s[p]!=','&&s[p]!='}')p++;}out.push_back(s.substr(st,p-st)+",");if(s[p]==',')p++;else if(s[p]=='}')break;else throw std::runtime_error("complex attribute separator");}return out;}
inline std::vector<std::string> catparts(const std::string&s){std::vector<std::string>out;if(s=="null")return out;if(s.front()!='"'||s.back()!='"')throw std::runtime_error("complex category parse");size_t p=1;while(1){size_t e=s.find(", ",p);if(e==std::string::npos){out.push_back(s.substr(p,s.size()-p-1)+", ");break;}out.push_back(s.substr(p,e-p)+", ");p=e+2;}return out;}
