inline void encode_hours(Bytes&out,const std::vector<std::string>&input){std::unordered_map<std::string,uint32_t>rm,tm;std::vector<std::string>rd,td;std::vector<uint32_t>ri,freq;for(auto&s:input){auto it=rm.emplace(s,rd.size());if(it.second){rd.push_back(s);freq.push_back(0);}ri.push_back(it.first->second);freq[it.first->second]++;}std::vector<uint32_t>order(rd.size());for(size_t j=0;j<order.size();j++)order[j]=j;std::sort(order.begin(),order.end(),[&](auto a,auto b){return freq[a]!=freq[b]?freq[a]>freq[b]:a<b;});std::vector<uint32_t>rank(rd.size());struct Pattern{unsigned mask,change;std::vector<uint32_t>times;};std::vector<Pattern>pat;uint32_t exn=0;static const char*days[]={"Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"};for(auto x:order){rank[x]=pat.size();auto&s=rd[x];exn+=s.size();Pattern pa{};if(s=="null")pa.mask=128;else{size_t p=1;int lastday=-1;std::string prev;while(p+1<s.size()){size_t e=quoted_end(s,p);auto key=s.substr(p+1,e-p-2);unsigned day=0;while(day<7&&key!=days[day])day++;if(day>=7||int(day)<=lastday)throw std::runtime_error("complex hour day order");lastday=day;pa.mask|=1<<day;p=e;if(s[p++]!=':')throw std::runtime_error("complex hour colon");e=quoted_end(s,p);auto val=s.substr(p,e-p);if(pa.times.empty()||val!=prev){pa.change|=1<<day;auto it=tm.emplace(val,td.size());if(it.second)td.push_back(val);pa.times.push_back(it.first->second);}prev=val;p=e;if(s[p]==',')p++;else if(s[p]=='}')break;else throw std::runtime_error("complex hour separator");}}pat.push_back(std::move(pa));}
 std::vector<uint32_t>tf(td.size());for(auto&p:pat)for(auto x:p.times)tf[x]++;std::vector<uint32_t>to(td.size()),tr(td.size());for(size_t j=0;j<to.size();j++)to[j]=j;std::sort(to.begin(),to.end(),[&](auto a,auto b){return tf[a]!=tf[b]?tf[a]>tf[b]:a<b;});std::vector<std::string>ts;for(auto x:to){tr[x]=ts.size();ts.push_back(std::move(td[x]));}pack_dict(out,ts);Bytes ps;unsigned tt=threshold(ts.size());std::unordered_map<uint32_t,uint32_t>combmap;std::vector<uint32_t>comb,masks;for(auto&p:pat){uint32_t code=p.mask|(p.change<<8);auto it=combmap.emplace(code,comb.size());if(it.second)comb.push_back(code);masks.push_back(it.first->second);for(auto x:p.times)putid(ps,tr[x],tt);}p32(out,pat.size());p32(out,exn);p32(out,comb.size());for(auto v:comb)p16(out,v);pack_huff(out,masks,comb.size());p32(out,ps.size());out.insert(out.end(),ps.begin(),ps.end());Bytes rs;unsigned rt=threshold(pat.size());for(auto x:ri)putid(rs,rank[x],rt);p32(out,rs.size());out.insert(out.end(),rs.begin(),rs.end());}
inline Bytes encode(const std::vector<std::string>&attrs,const std::vector<std::string>&cats,const std::vector<std::string>&hours){if(attrs.size()!=cats.size()||cats.size()!=hours.size())throw std::runtime_error("complex row size");Bytes out;p32(out,0x34435058);encode_tokens(out,attrs,true);encode_tokens(out,cats,false);encode_hours(out,hours);return out;}
